    let report = fixture.run("pinned-build", &names, "", "run_prepare", &[]);
    assert_eq!(report.process.status.unwrap().code(), Some(1));
    assert!(!fixture.root.join("order").exists());
    assert_eq!(
        fs::read_to_string(pin).unwrap(),
        format!("{}\n", "b".repeat(40))
    );
    fixture.finish();
