'fetch '*) [[ "$3" == "refs/heads/$FIXTURE_BRANCH" ]];;
'rev-parse '*) if [[ "$2" == "$FIXTURE_HEAD^" ]]; then printf '%s\n' "$FIXTURE_BASE"; elif [[ "$2" == "$FIXTURE_HEAD^{tree}" ]]; then printf '%s\n' "$FIXTURE_TREE"; else exit 96; fi;;
