fn runnable_statuses_refuse_unsupported_reasons_while_auxiliary_reason_is_admitted() {
    let family = json!({"models":[]});
    for status in ["certified", "candidate", "candidate_stateful"] {
        let mut parity = json!({"candidates":[{"llama_model":"somearch","status":status}]});
        assert!(validate(&parity, &family, &set(&["somearch"]), &set(&["somearch"])).is_ok());
        parity["candidates"][0]["unsupported_reason"] = json!("leftover");
        assert!(validate(&parity, &family, &set(&["somearch"]), &set(&["somearch"])).is_err());
    }
    let auxiliary = json!({"candidates":[{"llama_model":"encoder","status":"non_causal_aux","unsupported_reason":"non-causal encoder"}]});
    // Keep the legacy no-source shape, and independently exercise the row
    // policy with an actual inventoried source and no paired boundary.
    assert!(validate(&auxiliary, &family, &set(&[]), &set(&[])).is_ok());
    assert!(validate(&auxiliary, &family, &set(&["encoder"]), &set(&[])).is_ok());
    let mut malformed = auxiliary;
    malformed["candidates"][0]["unsupported_reason"] = json!({"not":"a string"});
    assert!(validate(&malformed, &family, &set(&["encoder"]), &set(&[])).is_err());
}

fn nested_selected_battery_uses_frozen_controller_plan_and_ignores_historical_planner() {
    let root = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../..")
        .canonicalize()
        .unwrap();
    let directory = tempfile::tempdir().unwrap();
    let source = directory
        .path()
        .join("outer checkout/selected historical source");
    selected_source(&root, &source);
    let plan = directory.path().join("admitted plan.json");
    let generated = planner(&source, &plan);
    assert!(generated.success(), "{}", report_summary(&generated));
    let before = fs::read(&plan).unwrap();
    let parsed: Json = serde_json::from_slice(&before).unwrap();
    assert_eq!(parsed["manifest"], "ci/llama-canary/family-certified.json");
    let models = parsed["selected_models"].as_array().unwrap();
    assert!(!models.is_empty() && models.len() <= 256);
    // Allow eight seconds for shared setup plus one per planned family.
    // Dry-run still launches multiple native planner/jq commands for every row.
    let execution = Duration::from_secs(8 + u64::try_from(models.len()).unwrap());
    let evidence = directory.path().join("battery evidence");
    let admitted = battery(&source, &plan, &evidence, "valid", execution);
    assert!(admitted.success(), "{}", report_summary(&admitted));
    assert_eq!(fs::read(&plan).unwrap(), before);
    assert_eq!(
        fs::read(evidence.join("valid/policy-plan.json")).unwrap(),
        before
    );
    assert!(!source.join("historical-planner-executed").exists());
    assert!(
        !String::from_utf8_lossy(&admitted.stderr.bytes_retained)
            .contains("forbidden-historical-planner")
    );
    let resolved = fs::read_to_string(evidence.join("valid/resolved-models.tsv")).unwrap();
    let actual = resolved
        .lines()
        .skip(1)
        .map(|line| line.split('|').next().unwrap())
        .collect::<Vec<_>>();
    let expected = models
        .iter()
        .map(|model| model["family"].as_str().unwrap())
        .collect::<Vec<_>>();
    assert_eq!(
        actual, expected,
        "every planned family must complete resolution"
    );
    rejected_omission(&source, parsed, directory.path(), &evidence);
}

fn copied_verify_wrapper_keeps_controller_and_candidate_authorities_independent() {
    let f = Fixture::new();
    let report = f.wrapper(
        &f.document,
        "verification_source_inspection verification-source-admit",
    );
    assert!(report.process.success(), "{:?}", report.process);
    let value: Json = serde_json::from_slice(report.stdout.unwrap().as_bytes()).unwrap();
    assert_eq!(value["candidate"], f.document["authority"]["candidate"]);
    f.no_transport_temps();
    for field in ["tree", "base", "digest", "root"] {
        let mut document = f.document.clone();
        match field {
            "tree" => document["authority"]["tree"] = json!("0".repeat(40)),
            "base" => {
                document["authority"]["base"] =
                    document["authority"]["controller"]["revision"].clone()
            }
            "digest" => {
                document["authority"]["controller"]["executable_sha256"] = json!("f".repeat(64))
            }
            "root" => {
                document["authority"]["root"] = document["authority"]["controller"]["root"].clone()
            }
            _ => unreachable!(),
        }
        let report = f.wrapper(
            &document,
            "verification_source_inspection verification-source-admit",
        );
        assert_eq!(report.process.outcome, process::Outcome::Exited);
        assert!(!report.process.success(), "admitted {field}");
