fn actual_changed_pin_agent_preflight_rejects_missing_failed_or_empty_version() {
    let action = crate::workflow_yaml::parse(
        &fs::read_to_string(repository().join(".github/actions/setup-canary-runner/action.yml"))
            .unwrap(),
    )
    .unwrap();
