        fs::read_to_string(directory.join("action.env"))
            .unwrap()
            .contains(&format!(
                "SKIPPY_REWRITER_LLVM_PREFIX={}/pinned",
                directory.display()
            ))
    );
    fs::remove_file(directory.join("pinned/lib/cmake/clang/ClangConfig.cmake")).unwrap();
    fs::write(directory.join("action.env"), "").unwrap();
