    assert_eq!(snapshot.untracked_files[0].bytes, 70 * 1024 * 1024);
    assert_eq!(snapshot.untracked_files[0].kind, "regular");
    assert_eq!(snapshot.untracked_files[0].sha256.len(), 64);
}
