            dependencies.into_iter().collect()
        );
    }
    let candidate = jobs.get("candidate").unwrap();
    let verification = jobs.get("verification").unwrap();
    assert_eq!(
        field(candidate, "uses"),
        "./.github/workflows/llama-canary-family-pass.yml"
    );
